$audited = 0;
$findings = [];
$allArticles = [];
$offset = 0;
$limit = 12;
do {
    $listResp = $tools->call("cms_list_articles", ["offset" => $offset, "limit" => $limit]);
    if (!isset($listResp->items) || !is_array($listResp->items)) {
        break;
    }
    foreach ($listResp->items as $item) {
        $allArticles[] = $item->id;
    }
    $offset = $listResp->next_offset !== null ? $listResp->next_offset : null;
} while ($offset !== null);

$articleMap = [];
// Batch fetch article details
for ($i = 0; $i < count($allArticles); $i += 12) {
    $batchIds = array_slice($allArticles, $i, 12);
    $articlesResp = $tools->call("cms_get_articles", ["ids" => $batchIds]);
    if (!isset($articlesResp->items) || !is_array($articlesResp->items)) {
        continue;
    }
    foreach ($articlesResp->items as $art) {
        $articleMap[$art->id] = [
            "title" => $art->title,
            "meta_description" => $art->meta_description,
            "image_id" => $art->image_id
        ];
    }
}
$audited = count($articleMap);
// Collect unique media ids
$mediaIds = [];
foreach ($articleMap as $a) {
    if (!empty($a["image_id"])) {
        $mediaIds[] = $a["image_id"];
    }
}
$mediaIds = array_values(array_unique($mediaIds));
$mediaMap = [];
for ($i = 0; $i < count($mediaIds); $i += 12) {
    $batch = array_slice($mediaIds, $i, 12);
    $mediaResp = $tools->call("cms_get_media", ["ids" => $batch]);
    if (!isset($mediaResp->items) || !is_array($mediaResp->items)) {
        continue;
    }
    foreach ($mediaResp->items as $m) {
        $mediaMap[$m->id] = $m->alt;
    }
}
// Build findings
foreach ($articleMap as $id => $info) {
    $issues = [];
    if (trim($info["meta_description"]) === "") {
        $issues[] = "missing_description";
    }
    $imgId = $info["image_id"];
    if (!empty($imgId) && array_key_exists($imgId, $mediaMap)) {
        $alt = $mediaMap[$imgId];
        if (trim($alt) === "") {
            $issues[] = "missing_alt";
        }
    }
    if (!empty($issues)) {
        $findings[] = ["id" => $id, "title" => $info["title"], "issues" => $issues];
    }
}
// sort findings by id
usort($findings, function($a, $b) { return $a["id"] <=> $b["id"]; });
return ["audited" => $audited, "findings" => $findings];

